  541	     * Which targets a phase may raid (RV-011): inactives in every phase, active
  542	     * players once a colony exists, and their fleets only once astrophysics 23 is
  543	     * behind the account. A probed-empty active target (ships is []) is a farm;
  544	     * an active target with ships, or unseen ships (null), waits for the late phase.
  545	     */
  546	    private function targetEligible(GamePhase $phase, EspionageReport $report): bool
  547	    {
  548	        if ($phase === GamePhase::Late) {
  549	            return true;
  550	        }
  551	
  552	        if ($this->targetInactive($report)) {
  553	            return true;
  554	        }
  555	
  556	        return $phase === GamePhase::Mid && $report->ships === [];
  557	    }
  558	
  559	    /**
  560	     * Whether the report's target is a farm: idle long enough to hit, read from
  561	     * the host's own inactivity rule (last login at least seven days ago). A
  562	     * report without a known owner is refused, never raided.
  563	     */
  564	    private function targetInactive(EspionageReport $report): bool
  565	    {
  566	        $targetUserId = (int) $report->planet_user_id;
  567	        if ($targetUserId <= 0 || !User::query()->whereKey($targetUserId)->exists()) {
  568	            return false;
  569	        }
  570	
  571	        // Fresh load: the inactivity stamp is the decision input and a cached
  572	        // player would carry the stamp from whenever the factory first built it.
  573	        return $this->playerServiceFactory->make($targetUserId, true)->isInactive();
  574	    }
  575	
  576	    /**
  577	     * The bashing limit, read from the account's own attack history on the target.
  578	     */
  579	    private function withinBashingLimit(int $playerId, int $targetPlanetId): bool
  580	    {
  581	        return ! app(DailyAttackBudget::class)->exhausted(
  582	            playerId: $playerId,
  583	            targetPlanetId: $targetPlanetId,
  584	            missionType: AttackMission::getTypeId(),
  585	            cap: self::BASHING_LIMIT,
  586	            windowHours: self::BASHING_WINDOW_HOURS,
  587	        );
  588	    }
  589	
  590	    /**
  591	     * A farm is hit on the storage-fill schedule, not back-to-back: the same
  592	     * target is left alone inside the cooldown however many sessions run, or
  593	     * the account reads as a script (FS-015). The last attack is the host's own
  594	     * fleet-mission history.
  595	     */
  596	    private function withinCooldown(int $playerId, int $targetPlanetId): bool
  597	    {
  598	        $lastAttack = FleetMission::query()
  599	            ->where('user_id', $playerId)
  600	            ->where('planet_id_to', $targetPlanetId)
  601	            ->where('mission_type', AttackMission::getTypeId())
  602	            ->orderByDesc('time_departure')
  603	            ->value('time_departure');
  604	
  605	        return $lastAttack === null || (int) $lastAttack <= now()->subHours(self::RAID_COOLDOWN_HOURS)->timestamp;
  606	    }
